#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

static long compute_gcd(long a, long b) {
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    /* Bad input: no conversion or extra characters */
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Overflow detection (strtol returns LONG_MIN on underflow/overflow) */
    if (a == LONG_MIN || b == LONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long abs_a = (a < 0) ? -a : a;
    long abs_b = (b < 0) ? -b : b;

    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    long gcd = compute_gcd(abs_a, abs_b);
    long lcm = (abs_a / gcd) * abs_b;
    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
